effect.shader:
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 uv = acScreenNorm;
    float t = floor(acTime / shakeInterval);

    // Convert angle to radians and get direction
    float rad = radians(angle);
    vec2 dir = vec2(cos(rad), sin(rad));

    // Jitter magnitude (modulated by random)
    float jitter = (rand(vec2(t, 0.0)) - 0.5) * 2.0;

    // Final shake offset vector
    vec2 shakeVec = dir * jitter * amplitude;

    const int MAX_SAMPLES = 32;
    int N = int(clamp(float(samples), 1.0, float(MAX_SAMPLES)));

    vec3 blurColor = vec3(0.0);
    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (i >= N) break;
        float factor = float(i) / float(N - 1);
        vec2 sampleUV = uv + shakeVec * factor;
        sampleUV = clamp(sampleUV, 0.0, 1.0);
        blurColor += texture2DCv(inputImg.texture, sampleUV).rgb;
    }
    blurColor /= float(N);
    gl_FragColor = vec4(blurColor, 1.0);
}
